def has_close_elements(numbers: List[float], threshold: float) -> bool:
    if not isinstance(numbers, list) or not all(isinstance(n, float) for n in numbers):
        raise ValueError("The 'numbers' parameter must be a list of floats.")
    if not isinstance(threshold, float):
        raise ValueError("The 'threshold' parameter must be a float.")
    if threshold < 0:
        raise ValueError("The 'threshold' must be a non-negative float.")

    numbers.sort()
    for i in range(len(numbers) - 1):
        if abs(numbers[i] - numbers[i + 1]) < threshold:
            return True
    return False

def separate_paren_groups(paren_string: str) -> List[str]:
    result = []
    current_group = []
    balance = 0

    for char in paren_string.replace(" ", ""):
        if char == '(':
            balance += 1
            current_group.append(char)
        elif char == ')':
            balance -= 1
            current_group.append(char)
            if balance == 0:
                result.append(''.join(current_group))
                current_group = []
        else:
            raise ValueError("Invalid character in input string. Only parentheses and spaces are allowed.")

    if balance != 0:
        raise ValueError("Unbalanced parentheses in input string.")

    return result

