def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    from collections import defaultdict

    # Create a grid to store the values
    grid = [[0] * N for _ in range(N)]
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    # DP table to store the maximum value collected by two paths
    dp = [[[-float('inf')] * N for _ in range(N)] for _ in range(N)]
    dp[0][0][0] = grid[0][0]

    # Fill the DP table
    for i in range(N):
        for j in range(N):
            for k in range(min(i + j + 1, N)):
                l = i + j - k
                if i > 0:
                    if j > 0:
                        dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k] + grid[i][j])
                    if k > 0:
                        dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k-1] + grid[i][j] + grid[i][k])
                if j > 0:
                    if k > 0:
                        dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k-1] + grid[i][j] + grid[l][k])
                    if l > 0:
                        dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][l] + grid[i][j])

    # The result is the maximum value collected by two paths reaching the bottom-right corner
    return max(dp[N-1][N-1][k] for k in range(N))

