def cantor_numbering(N: int) -> str:
    if not isinstance(N, int) or N <= 0:
        raise ValueError("N must be a positive integer.")

    level = 1
    while N > level:
        N -= level
        level += 1

    if level % 2 == 0:
        # Even level, go from left to right
        numerator = N
        denominator = level - N + 1
    else:
        # Odd level, go from right to left
        numerator = level - N + 1
        denominator = N

    return f"{numerator}/{denominator}"

def max_product(num_str: str, N: int, K: int) -> int:
    if not num_str.isdigit() or N <= 0 or K < 0 or K >= N:
        raise ValueError("Invalid input: num_str must be a digit string, N must be positive, and 0 <= K < N.")

    def split_and_multiply(parts):
        product = 1
        for part in parts:
            product *= int(part)
        return product

    max_product = 0
    from itertools import combinations

    for positions in combinations(range(1, N), K):
        parts = [num_str[i:j] for i, j in zip([0] + list(positions), list(positions) + [N])]
        current_product = split_and_multiply(parts)
        if current_product > max_product:
            max_product = current_product

    return max_product

