def verify_isbn(isbn: str) -> str:
    def calculate_checksum(isbn: str) -> str:
        # Remove hyphens and convert to list of characters
        chars = isbn.replace('-', '')
        total = 0
        for i in range(9):
            total += int(chars[i]) * (10 - i)
        checksum = 11 - (total % 11)
        return 'X' if checksum == 10 else str(checksum % 11)

    try:
        # Validate input format
        if len(isbn) != 13 or isbn[1] != '-' or isbn[5] != '-' or isbn[11] != '-':
            raise ValueError("Invalid ISBN format")

        # Extract parts of ISBN
        prefix, group, registrant, publication, checksum = isbn.split('-')

        # Calculate the correct checksum
        correct_checksum = calculate_checksum(isbn[:-1])

        # Compare the provided checksum with the calculated one
        if checksum == correct_checksum:
            return "Right"
        else:
            return f"{prefix}-{group}-{registrant}-{correct_checksum}"

    except Exception as e:
        raise ValueError(f"Error verifying ISBN: {e}")

def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    if M <= 0 or N <= 0 or K < 0 or L < 0 or D < 0:
        raise ValueError("Invalid dimensions or number of aisles/chatting pairs.")
    if any(not (1 <= x <= M and 1 <= y <= N and 1 <= p <= M and 1 <= q <= N) for x, y, p, q in chatting_pairs):
        raise ValueError("Chatting pairs must be within the classroom dimensions.")

    horizontal_separations = [0] * (M + 1)
    vertical_separations = [0] * (N + 1)

    for x, y, p, q in chatting_pairs:
        if x == p:  # Same row, vertical aisle can separate
            if y < q:
                vertical_separations[y + 1] += 1
            else:
                vertical_separations[q + 1] += 1
        elif y == q:  # Same column, horizontal aisle can separate
            if x < p:
                horizontal_separations[x + 1] += 1
            else:
                horizontal_separations[p + 1] += 1

    # Find the best K horizontal and L vertical positions
    best_horizontal_positions = sorted(range(1, M + 1), key=lambda i: horizontal_separations[i], reverse=True)[:K]
    best_vertical_positions = sorted(range(1, N + 1), key=lambda j: vertical_separations[j], reverse=True)[:L]

    return (' '.join(map(str, best_horizontal_positions)), ' '.join(map(str, best_vertical_positions)))

def count_passing_ways(n: int, m: int) -> int:
    if n <= 0 or m < 0:
        raise ValueError("Number of students must be positive and number of passes must be non-negative.")

    # dp[i][j] will store the number of ways to reach student j after i passes
    dp = [[0] * n for _ in range(m + 1)]
    dp[0][0] = 1  # Starting point

    for i in range(1, m + 1):
        for j in range(n):
            dp[i][j] = dp[i - 1][(j - 1) % n] + dp[i - 1][(j + 1) % n]

    return dp[m][0]

