def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    if n < 0 or m < 0:
        raise ValueError("Budget and number of items must be non-negative.")
    if not all(isinstance(item, tuple) and len(item) == 2 for item in items):
        raise ValueError("Items must be a list of tuples with two integers each.")
    if not all(isinstance(price, int) and isinstance(value, int) and price >= 0 and value >= 0 for price, value in items):
        raise ValueError("Item prices and values must be non-negative integers.")

    dp = [0] * (n + 1)
    for price, value in items:
        for budget in range(n, price - 1, -1):
            dp[budget] = max(dp[budget], dp[budget - price] + price * value)

    return dp[n]

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    if not isinstance(n, int) or n < 0:
        raise ValueError("The degree n must be a non-negative integer.")
    if not isinstance(coeffs, list) or len(coeffs) != n + 1:
        raise ValueError("Coeffs must be a list of integers with length n+1.")

    terms = []
    for i, coeff in enumerate(coeffs):
        degree = n - i
        if coeff == 0:
            continue

        sign = '+' if coeff > 0 else '-'
        abs_coeff = abs(coeff)

        if abs_coeff == 1 and degree != 0:
            coeff_str = ''
        else:
            coeff_str = str(abs_coeff)

        if degree > 1:
            var_str = f'x^{degree}'
        elif degree == 1:
            var_str = 'x'
        else:
            var_str = ''

        if not terms:
            terms.append(f'{coeff_str}{var_str}' if coeff > 0 else f'-{coeff_str}{var_str}')
        else:
            terms.append(f'{sign}{coeff_str}{var_str}')

    return ''.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for e, o in zip(encoded, original):
        if e in mapping:
            if mapping[e] != o:
                return "Failed"
        else:
            mapping[e] = o

    if len(mapping) != len(set(original)):
        return "Failed"

    try:
        decoded_message = ''.join(mapping[m] for m in message)
    except KeyError:
        return "Failed"

    return decoded_message

def largest_prime_factor(n: int) -> int:
    if n <= 1:
        raise ValueError("Input must be a positive integer greater than 1.")

    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return n // i

    return n

def count_partitions(n: int, k: int, x: int) -> int:
    if n < k * x:
        return 0
    if k == 1:
        return 1 if n >= x else 0
    if k == 0:
        return 1 if n == 0 else 0

    def helper(n, k, x, start):
        if k == 0:
            return 1 if n == 0 else 0
        if n < k * start:
            return 0
        count = 0
        for i in range(start, (n // k) + 1):
            count += helper(n - i, k - 1, x, i)
        return count

    return helper(n, k, x, x)

def count_sequences(n: int, last: int, memo: dict) -> int:
    if n <= 0 or last <= 0:
        raise ValueError("Both n and last must be positive integers.")

    if last in memo:
        return memo[last]

    if last == 1:
        return 1

    count = 1  # The sequence consisting of just the starting number
    for i in range(1, last // 2 + 1):
        count += count_sequences(n, i, memo)

    memo[last] = count
    return count

def count_coprime_pairs(x0: int, y0: int) -> int:
    if x0 <= 0 or y0 <= 0:
        raise ValueError("Both x0 and y0 must be positive integers.")
    if y0 % x0 != 0:
        return 0

    from math import gcd

    count = 0
    quotient = y0 // x0

    for a in range(1, int(quotient**0.5) + 1):
        if quotient % a == 0:
            b = quotient // a
            if gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2

    return count

def preorder_traversal(inorder: str, postorder: str) -> str:
    if not inorder or not postorder or len(inorder) != len(postorder):
        raise ValueError("Inorder and postorder traversals must be non-empty and of the same length.")

    def build_tree(in_start, in_end, post_start, post_end):
        if post_start > post_end or in_start > in_end:
            return None

        # The last element in postorder traversal is the root
        root_value = postorder[post_end]
        root = TreeNode(root_value)

        # Find the index of the root in inorder traversal
        in_index = inorder.index(root_value, in_start, in_end + 1)

        # Calculate the size of the left subtree
        left_subtree_size = in_index - in_start

        # Recursively build the left and right subtrees
        root.left = build_tree(in_start, in_index - 1, post_start, post_start + left_subtree_size - 1)
        root.right = build_tree(in_index + 1, in_end, post_start + left_subtree_size, post_end - 1)

        return root

    def preorder(node):
        if not node:
            return ""
        return node.val + preorder(node.left) + preorder(node.right)

    class TreeNode:
        def __init__(self, val):
            self.val = val
            self.left = None
            self.right = None

    root = build_tree(0, len(inorder) - 1, 0, len(postorder) - 1)
    return preorder(root)

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    from collections import deque

    if not isinstance(A, str) or not isinstance(B, str) or not isinstance(rules, list):
        raise ValueError("Invalid input types")

    if A == B:
        return 0

    queue = deque([(A, 0)])
    visited = set([A])

    while queue:
        current, steps = queue.popleft()

        if steps >= 10:
            continue

        for src, tgt in rules:
            start = 0
            while start <= len(current) - len(src):
                pos = current.find(src, start)
                if pos != -1:
                    new_string = current[:pos] + tgt + current[pos + len(src):]
                    if new_string == B:
                        return steps + 1
                    if new_string not in visited:
                        visited.add(new_string)
                        queue.append((new_string, steps + 1))
                else:
                    break
                start = pos + 1

    return "NO ANSWER!"

def find_min_n_greater_than_k(k: int) -> int:
    if k <= 0:
        raise ValueError("k must be a positive integer")

    harmonic_sum = 0.0
    n = 1

    while harmonic_sum <= k:
        harmonic_sum += 1 / n
        n += 1

    return n - 1

def is_prime(num: int) -> bool:
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_numbers(n, rules) -> int:
    from collections import deque, defaultdict

    # Create a transformation map from the rules
    transform_map = defaultdict(set)
    for x, y in rules:
        transform_map[x].add(y)

    # Convert the number to a string for easier manipulation
    original_number = str(n)
    queue = deque([original_number])
    visited = set([original_number])

    while queue:
        current_number = queue.popleft()

        # Try transforming each digit
        for i in range(len(current_number)):
            digit = int(current_number[i])
            if digit in transform_map:
                for new_digit in transform_map[digit]:
                    new_number = current_number[:i] + str(new_digit) + current_number[i+1:]
                    if new_number not in visited:
                        visited.add(new_number)
                        queue.append(new_number)

    return len(visited)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    try:
        for participant, stmts in statements.items():
            for stmt in stmts:
                # Ignore statements about the day of the week
                if any(day in stmt for day in days_of_week):
                    continue

                # Check if the statement is about guilt
                if "guilty" in stmt:
                    # Determine if the statement is a claim or accusation
                    if participant == scenario:
                        # Participant is claiming guilt
                        if participant in liar_count:
                            # Liars cannot claim guilt if they are the criminal
                            return False
                    else:
                        # Participant is accusing someone else
                        accused = stmt.split()[0].upper()
                        if accused == scenario:
                            if participant not in liar_count:
                                # Non-liars cannot accuse the criminal correctly
                                return False
                elif "not guilty" in stmt:
                    # Determine if the statement is a claim or accusation
                    if participant == scenario:
                        # Participant is claiming innocence
                        if participant in liar_count:
                            # Liars cannot claim innocence if they are the criminal
                            return True
                        else:
                            # Non-liars cannot claim innocence if they are the criminal
                            return False
                    else:
                        # Participant is accusing someone else of innocence
                        accused = stmt.split()[0].upper()
                        if accused == scenario:
                            if participant in liar_count:
                                # Liars cannot accuse the criminal of being innocent correctly
                                return True
                            else:
                                # Non-liars cannot accuse the criminal of being innocent correctly
                                return False
        return True
    except Exception as e:
        raise ValueError(f"An error occurred: {e}")

def calculate_score(system: int, points: str) -> list:
    if system not in [11, 21]:
        raise ValueError("System must be either 11 or 21.")
    if not all(char in 'WL' for char in points):
        raise ValueError("Points string must only contain 'W' and 'L' characters.")

    player_score = 0
    opponent_score = 0
    scores = []

    for point in points:
        if point == 'W':
            player_score += 1
        elif point == 'L':
            opponent_score += 1

        if (player_score >= system or opponent_score >= system) and abs(player_score - opponent_score) >= 2:
            scores.append(f"{player_score}:{opponent_score}")
            player_score = 0
            opponent_score = 0

    if player_score > 0 or opponent_score > 0:
        scores.append(f"{player_score}:{opponent_score}")

    return scores

def catalan_number(n: int) -> int:
    if n < 0:
        raise ValueError("The input must be a non-negative integer.")

    # Base case
    if n == 0:
        return 1

    # Create a list to store the catalan numbers up to n
    catalan = [0] * (n + 1)
    catalan[0] = 1

    # Fill the catalan array using the recursive formula
    for i in range(1, n + 1):
        for j in range(i):
            catalan[i] += catalan[j] * catalan[i - j - 1]

    return catalan[n]

