def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    if T < 0 or M < 0:
        raise ValueError("Time and number of herbs must be non-negative.")
    if len(herbs) != M:
        raise ValueError("The number of herbs does not match the provided list length.")

    # Initialize a list to store the maximum value that can be obtained for each time limit
    dp = [0] * (T + 1)

    # Iterate over each herb
    for time, value in herbs:
        # Update the dp array from back to front to avoid using the same herb multiple times
        for t in range(T, time - 1, -1):
            dp[t] = max(dp[t], dp[t - time] + value)

    # The maximum value that can be obtained with the given time limit is stored in dp[T]
    return dp[T]

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    if V < 0 or n < 0 or any(v < 0 for v in volumes):
        raise ValueError("Volume, number of items, and item volumes must be non-negative.")
    if n != len(volumes):
        raise ValueError("The number of items must match the length of the volumes list.")

    # Initialize a DP array where dp[i] will be True if a subset with volume i can be formed
    dp = [False] * (V + 1)
    dp[0] = True  # A subset with volume 0 is always possible (empty subset)

    # Update the dp array for each item
    for volume in volumes:
        for j in range(V, volume - 1, -1):
            if dp[j - volume]:
                dp[j] = True

    # Find the maximum volume that can be achieved which is less than or equal to V
    max_achievable_volume = max(i for i, can_form in enumerate(dp) if can_form)

    # The minimum remaining space is the total capacity minus the maximum achievable volume
    return V - max_achievable_volume

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7

    # dp[i][j] will store the number of ways to arrange j pots using the first i types of flowers
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Base case: There's one way to arrange 0 pots (by choosing no flowers)
    for i in range(n + 1):
        dp[i][0] = 1

    # Fill the dp table
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            dp[i][j] = dp[i - 1][j]  # Case 1: Do not use any of the ith type of flower
            for k in range(1, min(j, a[i - 1]) + 1):
                dp[i][j] = (dp[i][j] + dp[i - 1][j - k]) % MOD  # Case 2: Use k pots of the ith type of flower

    return dp[n][m]

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    if not key.isalpha() or not ciphertext.isalpha():
        raise ValueError("Key and ciphertext must consist only of alphabetic characters.")

    key = key.lower()
    ciphertext = ciphertext.lower()
    decrypted_text = []

    key_length = len(key)
    key_as_int = [ord(i) for i in key]
    ciphertext_int = [ord(i) for i in ciphertext]

    for i in range(len(ciphertext_int)):
        value = (ciphertext_int[i] - key_as_int[i % key_length]) % 26
        decrypted_text.append(chr(value + 97))

    return ''.join(decrypted_text)

def mod_inverse(a, b):
    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        gcd, x1, y1 = extended_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return gcd, x, y

    gcd, x, _ = extended_gcd(a, b)
    if gcd != 1:
        return None
    else:
        return x % b

def find_most_unhappy_day(schedule) -> int:
    if not isinstance(schedule, list) or len(schedule) != 7:
        raise ValueError("Schedule must be a list of 7 tuples.")

    max_unhappiness = 0
    most_unhappy_day = 0

    for i, (school_hours, extra_hours) in enumerate(schedule):
        if not (isinstance(school_hours, int) and isinstance(extra_hours, int)):
            raise ValueError("Each tuple in the schedule must contain two integers.")

        total_hours = school_hours + extra_hours
        unhappiness = total_hours - 8

        if unhappiness > max_unhappiness:
            max_unhappiness = unhappiness
            most_unhappy_day = i + 1

    return most_unhappy_day

def next_permutation(perm: list) -> bool:
    if not isinstance(perm, list) or not all(isinstance(x, int) for x in perm):
        raise ValueError("Input must be a list of integers.")

    n = len(perm)
    if n <= 1:
        return False

    # Step 1: Find the largest index k such that perm[k] < perm[k + 1]
    k = -1
    for i in range(n - 2, -1, -1):
        if perm[i] < perm[i + 1]:
            k = i
            break

    # If no such index exists, the permutation is the last permutation
    if k == -1:
        return False

    # Step 2: Find the largest index l greater than k such that perm[k] < perm[l]
    l = -1
    for i in range(n - 1, k, -1):
        if perm[k] < perm[i]:
            l = i
            break

    # Step 3: Swap the value of perm[k] with that of perm[l]
    perm[k], perm[l] = perm[l], perm[k]

    # Step 4: Reverse the sequence from perm[k + 1] up to and including the final element
    perm[k + 1:] = reversed(perm[k + 1:])

    return True

def jinjin_savings_plan(budgets: List[int]) -> int:
    if len(budgets) != 12:
        raise ValueError("The budgets list must contain exactly 12 integers.")

    pocket_money_per_month = 300
    savings = 0

    for month in range(12):
        remaining = pocket_money_per_month - budgets[month]
        if remaining < 0:
            return -(month + 1)
        savings += (remaining // 100) * 100

    savings_with_interest = savings * 1.2
    return int(savings_with_interest)

def minimum_students_to_leave(heights):
    if not heights:
        return 0

    n = len(heights)
    left_increasing = [1] * n
    right_increasing = [1] * n

    for i in range(1, n):
        if heights[i] > heights[i - 1]:
            left_increasing[i] = left_increasing[i - 1] + 1

    for i in range(n - 2, -1, -1):
        if heights[i] > heights[i + 1]:
            right_increasing[i] = right_increasing[i + 1] + 1

    min_students_to_leave = n
    for i in range(n):
        total_students_in_choir = left_increasing[i] + right_increasing[i] - 1
        students_to_leave = n - total_students_in_choir
        min_students_to_leave = min(min_students_to_leave, students_to_leave)

    return min_students_to_leave

def sort_students(student_scores):
    try:
        # Validate input
        if not isinstance(student_scores, list):
            raise ValueError("Input must be a list of tuples.")
        for student in student_scores:
            if not isinstance(student, tuple) or len(student) != 3:
                raise ValueError("Each student entry must be a tuple of (student_number, total_score, Chinese_score).")
            if not all(isinstance(x, (int, float)) for x in student[1:]):
                raise ValueError("Scores must be numbers.")
            if not isinstance(student[0], int):
                raise ValueError("Student number must be an integer.")

        # Sort the list based on the given criteria
        sorted_students = sorted(student_scores, key=lambda x: (-x[1], -x[2], x[0]))
        return sorted_students

    except Exception as e:
        raise RuntimeError(f"An error occurred: {e}")

def min_groups(w, n, prices):
    if not isinstance(w, int) or not isinstance(n, int) or not isinstance(prices, list):
        raise ValueError("Invalid input types")
    if w <= 0 or n <= 0:
        raise ValueError("w and n must be positive integers")
    if len(prices) != n:
        raise ValueError("The length of prices must be equal to n")
    if any(not isinstance(price, int) or price <= 0 for price in prices):
        raise ValueError("All prices must be positive integers")

    prices.sort()
    left, right = 0, n - 1
    groups = 0

    while left <= right:
        if prices[left] + prices[right] <= w:
            left += 1
        right -= 1
        groups += 1

    return groups

def hanoi_double_iterative(n: int) -> int:
    if n < 1:
        raise ValueError("The number of disc pairs must be at least 1.")

    # Base case for 1 pair of discs
    if n == 1:
        return 2

    # Initialize the number of moves for 1 pair of discs
    moves = 2

    # Iteratively calculate the number of moves for n pairs of discs
    for i in range(2, n + 1):
        moves = 3 * moves + 2

    return moves

def total_smoked_cigarettes(n, k):
    if not isinstance(n, int) or not isinstance(k, int):
        raise ValueError("Both n and k must be integers.")
    if n < 0 or k <= 1:
        raise ValueError("n must be non-negative and k must be greater than 1.")

    total_smoked = n
    butts = n

    while butts >= k:
        new_cigarettes = butts // k
        total_smoked += new_cigarettes
        butts = butts % k + new_cigarettes

    return total_smoked
